const onboardingRunItems = `-- name: OnboardingRunItems :many
SELECT id, organization_id, run_id, item_key, kind, label, source, status, entity_id, entity_uuid, previous, error, undone_at, created_at FROM onboarding_setup_items
WHERE organization_id = $1 AND run_id = $2
ORDER BY id
`

type OnboardingRunItemsParams struct {
	OrganizationID int64 `json:"organization_id"`
	RunID          int64 `json:"run_id"`
}

func (q *Queries) OnboardingRunItems(ctx context.Context, arg OnboardingRunItemsParams) ([]OnboardingSetupItem, error) {
	rows, err := q.db.Query(ctx, onboardingRunItems, arg.OrganizationID, arg.RunID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OnboardingSetupItem{}
	for rows.Next() {
		var i OnboardingSetupItem
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.RunID,
			&i.ItemKey,
			&i.Kind,
			&i.Label,
			&i.Source,
			&i.Status,
			&i.EntityID,
			&i.EntityUuid,
			&i.Previous,
			&i.Error,
			&i.UndoneAt,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

